CREATE TEMPORARY VIEW max_date_view_${grass_region_without_quote} AS
select
    max(grass_date)  as max_date
from rcmd_feature.nap_trending_pool_v2
where grass_region = ${grass_region}
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_nap_trending_pool_df
PARTITION (grass_region = ${grass_region} ,local_date = ${local_date} )
select  T1.item_id
        ,T1.shop_id
        ,T2.global_be_category_id
        ,T2.global_be_category
from    (
    select  item_id
            ,max(shop_id) as shop_id
    from    rcmd_feature.nap_trending_pool_v2
    where   grass_date = (SELECT max_date FROM max_date_view_${grass_region_without_quote})
    and     grass_region = ${grass_region}
    group by 1
) as T1
left join (
    select  item_id
            ,max(global_be_category) as global_be_category
            ,max(global_be_category_id) as global_be_category_id
    from    srdi_mart.dim_sr_data_warehouse_item
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
      group by 1
) as T2
on      T1.item_id = T2.item_id
